@namespace sv_95212fe7607d44fa8677735b1afc9b1d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
            @if (stepIndex < StepNames.Length - 1)
            {
                <li class="step-connector @(stepIndex < CurrentStep ? "completed" : "")" aria-hidden="true"></li>
            }
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepStatus(int step)
    {
        if (step < CurrentStep) return "completed";
        if (step == CurrentStep) return "active";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_95212fe7607d44fa8677735b1afc9b1d.Components.Pages.Apply

<div class="step-form personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name <span class="required">*</span></label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email <span class="required">*</span></label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" class="form-control" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone <span class="required">*</span></label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" class="form-control" />
    </div>

    <div class="form-group">
        <label for="address">Address <span class="required">*</span></label>
        <textarea id="address" @bind="Address" @bind:event="oninput" class="form-control" rows="2"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @(_isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Email);
            _isValidating = false;
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_95212fe7607d44fa8677735b1afc9b1d.Components.Pages.Apply

<div class="work-entry-form card">
    <div class="card-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-danger" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>
    <div class="card-body">
        <div class="form-group">
            <label>Company Name <span class="required">*</span></label>
            <input type="text" value="@Company" @oninput="e => { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title <span class="required">*</span></label>
            <input type="text" value="@Title" @oninput="e => { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" class="form-control" />
        </div>
        <div class="form-row">
            <div class="form-group half">
                <label>Start Date <span class="required">*</span></label>
                <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")); NotifyChanged(); }" class="form-control" />
            </div>
            <div class="form-group half">
                <label>End Date</label>
                <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" class="form-control" disabled="@IsCurrent" />
            </div>
        </div>
        <div class="form-group checkbox-group">
            <input type="checkbox" id="current-@Index" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
            <label for="current-@Index">I currently work here</label>
        </div>
        <div class="form-group">
            <label>Description</label>
            <textarea value="@Description" @oninput="e => { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" class="form-control" rows="3"></textarea>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync((Index, Company, Title, StartDate, EndDate, IsCurrent, Description));
    }
}

@namespace sv_95212fe7607d44fa8677735b1afc9b1d.Components.Pages.Apply

<div class="step-form work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var entry = Entries[i];
        var idx = i;
        <WorkEntryForm Index="idx"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="() => RemoveEntry(idx)"
                       OnChanged="HandleEntryChanged" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        StateHasChanged();
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
            StateHasChanged();
        }
    }

    private void HandleEntryChanged((int Index, string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description) data)
    {
        if (data.Index < Entries.Count)
        {
            var entry = Entries[data.Index];
            entry.Company = data.Company;
            entry.Title = data.Title;
            entry.StartDate = data.StartDate;
            entry.EndDate = data.EndDate;
            entry.IsCurrent = data.IsCurrent;
            entry.Description = data.Description;
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                _validationError = "Each position must have a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

