@namespace sv_95212fe7607d44fa8677735b1afc9b1d.Components.Pages.Apply

<div class="step-form references-step">
    <h3>References</h3>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var r = References[i];
        var idx = i;
        <ReferenceForm Index="idx"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       ShowRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(idx)"
                       OnChanged="HandleReferenceChanged" />
    }

