{"file_text": "/* Job Application Form Styles */
.apply-page {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.apply-page h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    list-style: none;
    padding: 0;
    margin: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    flex: 0 0 auto;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.85rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #2ecc71;
    background: #2ecc71;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.checkmark {
    font-size: 1rem;
}

.step-label {
    font-size: 0.7rem;
    margin-top: 0.4rem;
    text-align: center;
    color: #666;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.25rem;
    margin-bottom: 1.2rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #2ecc71;
}

/* Step Forms */
.step-form {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 2rem;
}

.step-form h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    color: #333;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ddd;
    border-radius: 4px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-group.half {
    flex: 1;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

.required {
    color: #e74c3c;
}

.field-error {
    color: #e74c3c;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin: 1rem 0;
    font-size: 0.9rem;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #3451d1;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ddd;
    color: #666;
}

.btn-outline:hover:not(:disabled) {
    border-color: #999;
    color: #333;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.btn-danger {
    background: #e74c3c;
    color: #fff;
}

.btn-danger:hover {
    background: #c0392b;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3451d1;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.05rem;
}

/* Cards (work entries, references) */
.card {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    margin-bottom: 1rem;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-bottom: 1px solid #e8e8e8;
    border-radius: 6px 6px 0 0;
}

.card-header h5 {
    margin: 0;
    font-size: 0.95rem;
    color: #333;
}

.card-body {
    padding: 1rem;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
    font-family: inherit;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.char-count.warning {
    color: #e67e22;
    font-weight: 500;
}

/* Review Step */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h4 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
}

.review-data dd {
    margin: 0;
    color: #333;
}

.review-work-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-description {
    margin: 0.3rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #333;
    line-height: 1.6;
}

.text-muted {
    color: #888;
    font-size: 0.85rem;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: #2ecc71;
    color: #fff;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
}

.submission-confirmation h4 {
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.submission-confirmation p {
    color: #666;
}
