            <label>Job Title <span class="required">*</span></label>
            <input type="text" value="@Title" @oninput="OnTitleInput" class="form-control" />
        </div>
        <div class="form-row">
            <div class="form-group half">
                <label>Start Date <span class="required">*</span></label>
                <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChange" class="form-control" />
            </div>
            <div class="form-group half">
                <label>End Date</label>
                <input type="date" value="@EndDateString" @onchange="OnEndDateChange" class="form-control" disabled="@IsCurrent" />
            </div>
        </div>
